WITH SAA000_HISTORY_LIST AS (

), SDA600_HISTORY_LIST AS (

), RSFR_INST_HISTORY AS (

SELECT T11.*
  FROM (
        SELECT * FROM SDA600_HISTORY_LIST
        ) T11
  WHERE 1 = 1
    AND T11.INST_NO = #{INST_NO}     /* 기관번호*/
)
 SELECT T.*
   FROM RSFR_INST_HISTORY T
  WHERE 1 = 1
